sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    function setOptions(r, field) {
        r = JSON.parse(r);
        //console.log(r);
        //g_form.clearOptions(field.id);
        for (var x = 0; x < r.length; x++) {
            g_form.addOption(field.id, r[x].value.toString(), r[x].label.toString());
        }

    }
    try {

        var lang = g_lang;
        if (!lang) {
            lang = 'en';
        }
        var fields = [{
                id: 'choice.x_hccc_hoc_ohs_investigation_case.rw.discrimination_grounds_list',
                element: 'discrimination_grounds_list',
                table: 'x_hccc_hoc_ohs_h_and_v_rw'
            },
            {
                id: 'choice.x_hccc_hoc_ohs_investigation_case.initial_review.results_of_occurrence',
                element: 'results_of_occurrence',
                table: 'x_hccc_hoc_ohs_h_and_v_initial_review'
            }
        ];




        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            if (g_form.getElement(field.id) && g_form.getElement(field.id).options.length < 2) {

                var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSGetChoiceValues');
                ga.addParam('sysparm_name', 'getChoiceValues');
                ga.addParam('field', field.element);
                ga.addParam('table', field.table);
                ga.addParam('language', lang)

                ga.getXMLAnswer(setOptions, null, field);
            }

        }

    } catch (e) {
        jslog(e);
    }


}
